const CANON_WEBHOOKS = [
  { name: 'Reply classification', events: ['lead_replied'],
    url: 'https://n8n.coldunicorn.com/webhook/replies-classification' },
  { name: 'PDCA', events: ['tag_attached', 'tag_removed'],
    url: 'https://n8n.coldunicorn.com/webhook/bison-replies-hub' },
];
// preMQL and OOO are 16/16. MQL is NOT in this set: it exists in only 7 of 16, and that is not
// a gap — an MQL in Bison is born from the built-in Interested tag (16/16), and
// bison-lead-enrichment reads includes('interested') || includes('mql'). Creating MQL would
// give the client a second, worse-wired route to the same qualification.
const CANON_TAGS = ['preMQL', 'OOO'];
const CANON_CAMPAIGNS = ['OOO automation | general', 'OOO automation | male', 'OOO automation | female'];
// A webhook's identity is events + url, NEVER its name. UniTalk's is called
// "Reply Classification" against "Reply classification" on the other fifteen.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;
// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

// State BEFORE any write. Either returned as is, or merged with what was actually created.
const client = $('Resolve Client').first().json ?? {};
const key = $('Effective Key').first().json ?? {};

const step = (outcome, present = [], missing = [], error = null) => ({
  outcome, present, ...(missing.length ? { missing } : {}), ...(error ? { error } : {}),
});

// Each list can arrive as several items — /api/campaigns is paginated through links.next.
const collect = (nodeName) => {
  let items;
  try { items = $(nodeName).all(); } catch (e) { return { rows: [], error: describe(e) }; }
  const rows = [];
  let error = null;
  for (const item of items) {
    const j = item.json ?? {};
    if (j.error) { error = describe(j.message ?? j.error); continue; }
    if (Array.isArray(j.data)) rows.push(...j.data);
    else if (Array.isArray(j)) rows.push(...j);
  }
  return { rows, error };
};

const keyStep = key.key_source === 'stored' ? step('ok', ['client_sequencers.api_key'])
  : key.key_source === 'minted' ? step('created', ['minted and stored'])
  : step('missing', [], ['api_key'],
      key.mint_error ?? (isDryRun()
        ? 'no key stored; Bison has no token-list endpoint, so nothing can be reused'
        : 'mint did not run'));

const haveKey = Boolean(key.api_key);

const webhooks = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Webhooks');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((w) => hookKey(w.events, w.url));
  const missing = CANON_WEBHOOKS.map((c) => hookKey(c.events, c.url)).filter((k) => !present.includes(k));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const tags = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Tags');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  const present = rows.map((t) => String(t?.name ?? '').trim()).filter(Boolean);
  const missing = CANON_TAGS.filter((n) => !present.includes(n));
  return step(missing.length ? 'missing' : 'ok', present, missing);
})();

const campaigns = (() => {
  if (!haveKey) return step('skipped', [], [], 'no workspace key available');
  const { rows, error } = collect('List Campaigns');
  if (error) return step('skipped', [], [], `vendor call failed: ${error}`);
  // The vendor status is carried into `present`, not just the name. A campaign we created is a
  // DRAFT until a manager writes its sequence and starts it, and "OOO automation | general" alone
  // reads as if it were sending. Bent Iron PL's `939 general archived` is the same problem from
  // the other side: present, and not going to send anything either.
  const found = rows.map((c) => ({
    name: String(c?.name ?? '').trim(),
    status: String(c?.status ?? 'unknown').trim() || 'unknown',
  }));
  // Duplicates are reported explicitly — otherwise they are visible only at the vendor.
  const present = CANON_CAMPAIGNS
    .map((n) => ({ n, hits: found.filter((f) => f.name === n) }))
    .filter((x) => x.hits.length > 0)
    .map((x) => (x.hits.length > 1
      ? `${x.n} ×${x.hits.length} (${x.hits.map((h) => h.status).join(', ')})`
      : `${x.n} (${x.hits[0].status})`));
  const missing = CANON_CAMPAIGNS.filter((n) => !found.some((f) => f.name === n));
  const dup = present.some((p) => p.includes(' ×'));
  return step(
    missing.length ? 'missing' : 'ok',
    present,
    missing,
    dup ? 'duplicate OOO campaigns at the vendor — reported, never resolved by creating more' : null,
  );
})();

return [{ json: {
  client_id: $('Input').first().json.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: isDryRun(),
  resolved: ($('Resolve Workspace').first().json ?? {}).resolved ?? null,
  steps: { key: keyStep, webhooks, tags, campaigns },
} }];

// Fold N vendor responses back into one item. n8n preserves item order, so the i-th response
// belongs to the i-th planned element.
// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const planned = $('Plan Writes').all().map((i) => i.json);
const results = $input.all().map((i) => i.json ?? {});
const created = [];
const failed = [];
planned.forEach((p, i) => {
  const r = results[i] ?? {};
  // statusCode ONLY. The status field is the vendor's, not HTTP, and Number('ok') is NaN — reading
  // it as a code scores a failure as success.
  const code = Number(r.statusCode ?? 0);
  const bad = Boolean(r.error) || code >= 400;
  if (bad) failed.push(`${p.identity} — ${describe(r.message ?? r.error) ?? 'HTTP ' + code}`);
  else created.push(p.identity);
});
// A campaign's id is knowable only from its own create response, and the schedule call needs it.
// Same index correspondence the loop above relies on. Bison answers { data: { id } }.
const created_ids = {};
planned.forEach((p, i) => {
  if (p.kind !== 'campaign') return;
  const r = results[i] ?? {};
  const id = r.data?.id ?? r.id ?? null;
  if (id) created_ids[p.identity] = String(id);
});

return [{ json: { created, failed, created_ids } }];

// Fold N schedule responses back into one item, the same index correspondence Collect Creates
// relies on.
// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const planned = $('Plan Schedules').all().map((i) => i.json);
const results = $input.all().map((i) => i.json ?? {});
const scheduled = [];
const failed = [];
planned.forEach((p, i) => {
  const r = results[i] ?? {};
  // statusCode ONLY. The status field is the vendor's, not HTTP, and Number('ok') is NaN — reading
  // it as a code scores a failure as success.
  const code = Number(r.statusCode ?? 0);
  const bad = Boolean(r.error) || code >= 400;
  if (bad) failed.push(`${p.identity} — ${describe(r.message ?? r.error) ?? 'HTTP ' + code}`);
  else scheduled.push(p.identity);
});
return [{ json: { scheduled, failed } }];

// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

// The order here is shorter than in Aimfox, and that is a vendor limit, not a simplification:
// Bison has no GET for workspace tokens, so a key cannot be re-read. A key that was minted and
// not stored is lost for good and can only be reissued. That is what the old canvas did:
// it consumed data.plain_text_token inside the execution and wrote it nowhere.
const client = $('Resolve Client').first().json ?? {};

let minted = null;
let mint_error = null;
if ($('Mint Key').isExecuted) {
  const m = $('Mint Key').first().json ?? {};
  minted = m.data?.plain_text_token ?? m.plain_text_token ?? m.data?.token ?? null;
  if (!minted) mint_error = describe(m.message ?? m.error) ?? 'mint returned no token';
}

const stored = client.api_key || null;
const api_key = stored ?? minted;
const key_source = stored ? 'stored' : minted ? 'minted' : 'none';

// key_to_store is non-empty only when a key was just minted. For Bison that is not a convenience
// but the only chance: not writing it here loses it for good.
return [{ json: {
  api_key,
  key_source,
  key_to_store: key_source === 'minted' ? api_key : null,
  mint_error,
} }];

// n8n reports a node error as { message, error }, and error is an object. A naive String(err)
// gives `[object Object]` — a string that says nothing.
const describe = (v) => {
  if (v == null) return null;
  if (typeof v === 'string') return v;
  return v.message ?? v.description ?? (() => { try { return JSON.stringify(v); } catch (e) { return String(v); } })();
};

const out = $('Merge Outcomes').first().json;
const rec = $json ?? {};
const failed = Boolean(rec.error);
return [{ json: {
  ...out,
  // Workflow state, not a result field — the contract is additionalProperties:false. Same reason
  // aimfox-workspace-setup strips activate_campaign_id here.
  created_campaigns: undefined,
  recorded: !failed,
  ...(failed ? { record_error: describe(rec.message ?? rec.error) } : {}),
} }];

// One entry point for two triggers. A webhook puts the payload in body; the sub-workflow trigger
// puts it at the root. Without this node every $('Start') would throw on a webhook run.
const fromWebhook = $('Webhook').isExecuted;
const raw = fromWebhook ? ($('Webhook').first().json?.body ?? {}) : ($('Start').first().json ?? {});

// dry_run: anything but an EXPLICIT boolean false is a dry run. The string 'false' does not count.
// That matters more on an open webhook than in the UI: the body arrives from the network, and
// neither a forgotten field nor a wrong type may mean "write into the client's system".
return [{ json: {
  client_id: raw.client_id ?? null,
  workspace_id: raw.workspace_id ?? null,
  dry_run: raw.dry_run === false ? false : true,
  requested_by: raw.requested_by ?? null,
  via: fromWebhook ? 'webhook' : 'sub-workflow',
} }];

// One shape for Record and for the response. Runs both after creation and around it.
const base = $('Build Result').first().json;
const steps = JSON.parse(JSON.stringify(base.steps));

if ($('Collect Creates').isExecuted) {
  const { created = [], failed = [] } = $('Collect Creates').first().json ?? {};
  for (const name of ['webhooks', 'tags', 'campaigns']) {
    const st = steps[name];
    const wanted = st.missing ?? [];
    const done = wanted.filter((k) => created.includes(k));
    const bad = wanted.filter((k) => failed.some((f) => f.startsWith(k + ' —')));
    if (done.length) st.created = done;
    st.missing = wanted.filter((k) => !done.includes(k));
    if (!st.missing.length) delete st.missing;
    st.outcome = bad.length ? 'failed' : done.length ? 'created' : st.outcome;
    if (bad.length) st.error = failed.filter((f) => bad.some((k) => f.startsWith(k + ' —'))).join('; ');
  }
  // A campaign we just made is a draft, and `present` is the only line that says so. Without this
  // the card shows the name bare, which is how the list reads for a campaign that is actually
  // sending — the one distinction a manager has to act on.
  const madeNow = steps.campaigns.created ?? [];
  if (madeNow.length) {
    steps.campaigns.present = [...(steps.campaigns.present ?? []), ...madeNow.map((n) => `${n} (draft)`)];
  }
}

// The schedule is a second call on the campaign's own id, so it can only fail after the campaign
// exists. That is not a failed step: the draft is there and a manager can set the hours in the UI.
// It is recorded as an error on the step and nothing more.
if ($('Collect Schedules').isExecuted) {
  const { failed: scheduleFailed = [] } = $('Collect Schedules').first().json ?? {};
  if (scheduleFailed.length) {
    const st = steps.campaigns;
    st.error = [st.error, `created, schedule not set: ${scheduleFailed.join('; ')}`].filter(Boolean).join('; ');
  }
}

// campaigns is deliberately NOT part of state, even now that it creates. A draft campaign has no
// sequence and sends nothing, so folding it in would let `configured` mean "ready to send" when it
// is not — and OOO routing pointed at a draft fails silently, which is the FortumEnergia shape.
// The finding is not lost: it stays in steps.campaigns and shows in the portal as its own row.
const decided = [steps.key, steps.webhooks, steps.tags];
const good = (s) => s.outcome === 'ok' || s.outcome === 'created';
const state = decided.every(good) ? 'configured'
  : decided.every((s) => !good(s)) ? 'missing'
  : 'partial';

// Carried to Record and stripped again in Final Result — it is workflow state, not part of the
// result contract (which is additionalProperties:false). Empty on a dry run by construction:
// Collect Creates cannot have run.
const created_campaigns = $('Collect Creates').isExecuted
  ? Object.entries($('Collect Creates').first().json?.created_ids ?? {})
      .map(([name, external_id]) => ({ external_id: String(external_id), name }))
  : [];

return [{ json: { ...base, state, steps, created_campaigns } }];

const input = $('Input').first().json;
const client = $('Resolve Client').first().json ?? {};
const resolution = $('Resolve Workspace').first().json ?? {};

// A list request is not a verdict about anything: there is no client to have one. Its own state
// keeps the portal from rendering it as a provisioning outcome.
if (resolution.listing) {
  return [{ json: {
    client_id: null, client_name: null, sequencer: 'emailbison', dry_run: true,
    resolved: null, state: 'workspace_list', reason: null,
    candidates: resolution.candidates ?? [], steps: {},
  } }];
}

// A client that does not exist is the caller's error, not a provisioning state. But it has to
// be said out loud: a silent stop with status=success is how Audytel's leads disappeared.
const state = resolution.client_missing ? 'client_not_found' : 'needs_selection';
const reason = resolution.client_missing ? 'no client with that id — Resolve Client left-joins the connector, so a client without one still resolves'
  : resolution.ambiguous ? 'more than one workspace matches the client name'
  : resolution.list_error ? `could not list workspaces: ${resolution.list_error}`
  : 'no workspace matches the client name';

return [{ json: {
  client_id: input.client_id,
  client_name: client.client_name ?? null,
  sequencer: 'emailbison',
  dry_run: $('Input').first().json.dry_run !== false,
  resolved: null,
  state,
  reason,
  candidates: resolution.candidates ?? [],
  steps: {
    key: { outcome: 'skipped' }, webhooks: { outcome: 'skipped' },
    tags: { outcome: 'skipped' }, campaigns: { outcome: 'skipped' },
  },
} }];

// One item per campaign this run actually created. Never for one that already existed: its hours
// are the client's, and overwriting them is outside the canonical set (invariant 5).
// An empty array means Create Schedule does not execute — the same structural guard Plan Writes
// uses for dry runs, and the reason a dry run can never reach this branch at all.
//
// Mon-Fri 09:00-17:00 Europe/Warsaw is the house convention, copied verbatim from the old canvas
// (8uRWXHe9FIfglq1u, all three Create Campaign Schedule nodes). It is a starting point a manager
// changes in the Bison UI along with the sequence, not a claim about this client's hours.
const SCHEDULE = {
  monday: true, tuesday: true, wednesday: true, thursday: true, friday: true,
  saturday: false, sunday: false,
  start_time: '09:00', end_time: '17:00',
  timezone: 'Europe/Warsaw',
  save_as_template: false,
};

const { created_ids = {} } = $json;
return Object.entries(created_ids).map(([identity, id]) => ({ json: {
  identity,
  campaign_id: id,
  url: `https://go.gheads.com/api/campaigns/${id}/schedule`,
  body: SCHEDULE,
} }));

const CANON_WEBHOOKS = [
  { name: 'Reply classification', events: ['lead_replied'],
    url: 'https://n8n.coldunicorn.com/webhook/replies-classification' },
  { name: 'PDCA', events: ['tag_attached', 'tag_removed'],
    url: 'https://n8n.coldunicorn.com/webhook/bison-replies-hub' },
];
// preMQL and OOO are 16/16. MQL is NOT in this set: it exists in only 7 of 16, and that is not
// a gap — an MQL in Bison is born from the built-in Interested tag (16/16), and
// bison-lead-enrichment reads includes('interested') || includes('mql'). Creating MQL would
// give the client a second, worse-wired route to the same qualification.
const CANON_TAGS = ['preMQL', 'OOO'];
const CANON_CAMPAIGNS = ['OOO automation | general', 'OOO automation | male', 'OOO automation | female'];
// A webhook's identity is events + url, NEVER its name. UniTalk's is called
// "Reply Classification" against "Reply classification" on the other fifteen.
const hookKey = (events, url) => `${[...(events ?? [])].map(String).sort().join('+')} ${String(url ?? '').trim()}`;
const isDryRun = () => $('Input').first().json.dry_run !== false;

// One item per MISSING element. An empty array means Create Missing does not execute at all —
// that, not a flag, is how dry-run safety works here.
if (isDryRun()) return [];

const s = $json.steps ?? {};
const out = [];
for (const c of CANON_WEBHOOKS) {
  const id = hookKey(c.events, c.url);
  if ((s.webhooks?.missing ?? []).includes(id)) {
    out.push({ json: { kind: 'webhook', identity: id, url: 'https://go.gheads.com/api/webhook-url',
      body: { name: c.name, url: c.url, events: c.events } } });
  }
}
for (const name of CANON_TAGS) {
  if ((s.tags?.missing ?? []).includes(name)) {
    out.push({ json: { kind: 'tag', identity: name, url: 'https://go.gheads.com/api/tags', body: { name } } });
  }
}
// Campaigns are created as DRAFTS: name + type, nothing else. What was blocked was never the
// campaign, it was POST /campaigns/v1.1/{id}/sequence-steps — the copy on the old canvas is
// byte-identical across all three, in feminine Polish, with a hardcoded {PANIEKAMILU}. That call
// is not made here and must not be: a manager writes the sequence and starts the campaign.
// A draft with no sequence sends nothing, so creating one cannot produce a message.
for (const name of CANON_CAMPAIGNS) {
  if ((s.campaigns?.missing ?? []).includes(name)) {
    out.push({ json: { kind: 'campaign', identity: name, url: 'https://go.gheads.com/api/campaigns',
      body: { name, type: 'reply_followup' } } });
  }
}
return out;

